<content>import { useState, useRef } from "react";
import { Box, Button, Avatar, Typography, IconButton } from "@mui/material";
import { PhotoCamera, Delete } from "@mui/icons-material";
import { approvedIcons } from "../../theme/approvedIcons";

const AccountCircleIcon = approvedIcons.accountCircle;

interface AvatarUploadProps {
  currentAvatar: string | null;
  onAvatarChange: (base64: string | null) => void;
}

export const AvatarUpload = ({ currentAvatar, onAvatarChange }: AvatarUploadProps) => {
  const [preview, setPreview] = useState<string | null>(currentAvatar);
  const [error, setError] = useState<string>("");
  const fileInputRef = useRef<HTMLInputElement>(null);

  const resizeImage = (file: File): Promise<string> => {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();

      reader.onload = (e) => {
        const img = new Image();
        img.onload = () => {
          const canvas = document.createElement("canvas");
          const size = 200;
          canvas.width = size;
          canvas.height = size;

          const ctx = canvas.getContext("2d");
          if (!ctx) {
            reject(new Error("Failed to get canvas context"));
            return;
          }

          // Calculate dimensions to maintain aspect ratio
          let sx = 0, sy = 0, sWidth = img.width, sHeight = img.height;
          if (img.width > img.height) {
            sx = (img.width - img.height) / 2;
            sWidth = img.height;
          } else if (img.height > img.width) {
            sy = (img.height - img.width) / 2;
            sHeight = img.width;
          }

          ctx.drawImage(img, sx, sy, sWidth, sHeight, 0, 0, size, size);

          const base64 = canvas.toDataURL("image/jpeg", 0.9);
          resolve(base64);
        };
        img.onerror = () => reject(new Error("Failed to load image"));
        img.src = e.target?.result as string;
      };

      reader.onerror = () => reject(new Error("Failed to read file"));
      reader.readAsDataURL(file);
    });
  };

  const handleFileSelect = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setError("");

    // Validate file type
    if (!file.type.startsWith("image/")) {
      setError("Please select an image file");
      return;
    }

    // Validate file size (2MB)
    if (file.size > 2 * 1024 * 1024) {
      setError("Image must be smaller than 2MB");
      return;
    }

    try {
      const resizedBase64 = await resizeImage(file);
      setPreview(resizedBase64);
      onAvatarChange(resizedBase64);
    } catch (err) {
      setError("Failed to process image");
      console.error(err);
    }

    // Reset input
    if (fileInputRef.current) {
      fileInputRef.current.value = "";
    }
  };

  const handleRemove = () => {
    setPreview(null);
    onAvatarChange(null);
    setError("");
  };

  return (
    <Box sx={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 2 }}>
      <Avatar
        src={preview || undefined}
        sx={{
          width: 120,
          height: 120,
          bgcolor: "primary.main"
        }}
      >
        {!preview && <AccountCircleIcon sx={{ width: 80, height: 80 }} />}
      </Avatar>

      <Box sx={{ display: "flex", gap: 1, alignItems: "center" }}>
        <input
          ref={fileInputRef}
          accept="image/*"
          type="file"
          hidden
          onChange={handleFileSelect}
          aria-label="Upload avatar image"
        />
        <Button
          variant="outlined"
          startIcon={<PhotoCamera />}
          onClick={() => fileInputRef.current?.click()}
        >
          {preview ? "Change" : "Upload"}
        </Button>
        {preview && (
          <IconButton
            onClick={handleRemove}
            color="error"
            aria-label="Remove avatar"
            size="small"
          >
            <Delete />
          </IconButton>
        )}
      </Box>

      {error && (
        <Typography variant="caption" color="error" sx={{ textAlign: "center" }}>
          {error}
        </Typography>
      )}

      <Typography variant="caption" color="text.secondary" sx={{ textAlign: "center" }}>
        Square images work best. Max 2MB.
      </Typography>
    </Box>
  );
};
</content>
